function parseWith(source, ext, tokens) {
  const plugins = TS_EXTS.has(ext) ? TS_PLUGINS : FLOW_PLUGINS;
  return parse(source, {
    sourceType: 'module',
    allowImportExportEverywhere: true,
    allowReturnOutsideFunction: true,
    errorRecovery: true,
