    return '## 📦 Artefact: ' + asset.name + '\n\n' +
        'Folder `' + releaseArtefacts.resolveTemplate(asset.fromFolder, ticketKey) +
        '` has been archived to a ' + scmProvider + ' Release.\n\n' +
        '**Release:** ' + releaseUrl;
