function uploadAssets(inputs) {
    var results = [];
    var releaseUrl = null;

    for (var i = 0; i < inputs.assets.length; i++) {
        var asset = inputs.assets[i];
        if (!asset.fromFolder || !asset.name) {
            console.warn('⚠️  Asset missing fromFolder or name, skipping:', JSON.stringify(asset));
