// The linked-run decision tree: probe error → live (fail safe), absent run
// → 'no-run' zombie, active run → live, terminal run → completedRunVerdict,
// unknown vocabulary → live (fail safe).
function classifyLinkedRun(cr, runId, resolveRun, nowMs, graceMs) {
