    try {
        var inputs = resolveActionInputs(params);
        if (!inputs.ok) {
            ACTION_SKIP_LOGS[inputs.reason]();
            return { success: true, skipped: true };
        }

        console.log('=== cacheToReleases for', inputs.ticketKey, '(' + inputs.scmProvider + ') ===');
