    if (!ctx.ticketKey) {
        return { ok: false, reason: 'noTicketKey' };
    }

    var customParams = resolveCustomParams(params);
    var config = customParams.cacheToReleases;
    if (!config) {
        return { ok: false, reason: 'notConfigured' };
    }

    if (!hasConfiguredAssets(config)) {
