    if (!artefactRepo) {
        return { ok: false, reason: 'noArtefactRepository' };
    }

    var projectConfig = configLoader.loadProjectConfig(ctx.actualParams);
    return {
        ok: true,
        ticketKey: ctx.ticketKey,
        customParams: customParams,
        assets: config.assets,
