    .map(l => l.trim().split(/\s+/))
    .filter(c => c.length >= 5 && /\.(js|mjs|cjs)$/.test(c[1]) && !isNaN(parseFloat(c[c.length-1])));
  const scores = rows.map(c => parseFloat(c[c.length-1]));
  const prod = rows.filter(c => !/\/(unit-tests|test)\//.test(c[1]) || /\.cjs$/.test(c[1]) && /ci\//.test(c[1]));
  const prodScores = prod.map(c => parseFloat(c[c[c.length-1] !== undefined && !isNaN(parseFloat(c[c.length-1])) ? c.length-1 : c.length-1]));
  const over = scores.filter(x => x > 8).length;
  const prodOver = prodScores.filter(x => x > 8).length;
  console.log(label, '— ALL: max', Math.max(...scores), '| >8:', over, '|| PRODUCT-only: max', Math.max(...prodScores), '| >8:', prodOver);
}
stats('/tmp/crap-before-final.txt', 'BEFORE');
stats('/tmp/crap-after-final.txt', 'AFTER ');
